<?php
$currencyName=''; $balance=0; $precision=0;
foreach($balances as $b){ if((string)$b['currency_code']===$currency){ $currencyName=(string)($b['name']??$currency); $balance=(float)$b['balance']; $precision=(int)($b['precision']??0); break; } }
$currencyName=$currencyName?:$currency;
$firstPackage=$packages[0]??null;
$ratio=($firstPackage && (float)$firstPackage['pay_amount']>0) ? ((float)$firstPackage['amount']/(float)$firstPackage['pay_amount']) : 0;
?>
<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>钱包充值</title><link rel="stylesheet" href="/assets/css/style.css"><style>
.recharge-page{min-height:100vh;background:linear-gradient(180deg,#f6f8fb 0%,#fff 42%,#f7f8fb 100%);padding:22px 16px 72px}.recharge-shell{max-width:920px;margin:0 auto}.recharge-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:16px}.recharge-title{margin:0;color:#111827;font-size:28px;font-weight:950;letter-spacing:-.04em}.recharge-sub{margin-top:6px;color:#64748b;font-size:13px;line-height:1.7}.wallet-link{height:34px;border-radius:999px;padding:0 13px;display:inline-flex;align-items:center;text-decoration:none;border:1px solid #e2e8f0;background:#fff;color:#64748b;font-size:12px;font-weight:900}.alert{padding:10px 12px;border-radius:14px;margin-bottom:12px;font-size:13px}.alert.ok{background:#dcfce7;color:#15803d}.alert.err{background:#fee2e2;color:#b91c1c}.asset-panel{border:1px solid #e2e8f0;background:#fff;border-radius:22px;padding:16px;margin-bottom:14px;box-shadow:0 10px 28px rgba(15,23,42,.04)}.asset-current{display:flex;justify-content:space-between;gap:14px;align-items:end}.asset-current span{display:block;color:#94a3b8;font-size:12px;font-weight:900}.asset-current strong{display:block;margin-top:5px;color:#111827;font-size:30px;font-weight:600;letter-spacing:-.04em}.currency-tabs{display:flex;gap:8px;overflow-x:auto;margin-top:14px;padding-bottom:2px;scrollbar-width:none}.currency-tabs::-webkit-scrollbar{display:none}.currency-tabs a{flex:0 0 auto;border:1px solid #e2e8f0;background:#f8fafc;color:#64748b;text-decoration:none;border-radius:999px;padding:8px 13px;font-size:12px;font-weight:950}.currency-tabs a.active{background:#111827;color:#fff;border-color:#111827}.recharge-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);gap:14px}.recharge-card{border:1px solid #e2e8f0;background:#fff;border-radius:22px;padding:16px;box-shadow:0 10px 28px rgba(15,23,42,.04)}.card-title{font-size:17px;font-weight:950;color:#111827;margin-bottom:6px}.card-desc{font-size:12px;color:#94a3b8;line-height:1.7;margin-bottom:14px}.mode-tabs{display:flex;gap:8px;margin-bottom:14px}.mode-tabs button{height:34px;border-radius:999px;border:1px solid #e2e8f0;background:#f8fafc;color:#64748b;padding:0 13px;font-size:12px;font-weight:950}.mode-tabs button:disabled{opacity:.45;cursor:not-allowed}.mode-tabs button.active{background:#111827;color:#fff;border-color:#111827}.package-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.package-option{position:relative;text-align:center;border:1px solid #e2e8f0;background:#fff;border-radius:16px;padding:14px 8px;min-height:104px;display:grid;place-items:center;cursor:pointer}.package-option.active{border-color:#0284c7;background:#f0f9ff;box-shadow:0 0 0 1px rgba(2,132,199,.12)}.package-option b{display:block;font-size:18px;color:#111827;line-height:1.25}.package-option span{display:block;margin-top:7px;font-size:12px;color:#64748b;font-weight:800}.custom-panel{display:none;gap:10px}.custom-panel.active{display:grid}.custom-result{padding:12px;border-radius:14px;background:#f8fafc;color:#64748b;font-size:13px;line-height:1.7}.pay-methods{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.pay-methods label{height:34px;border-radius:999px;border:1px solid #e2e8f0;padding:0 11px;display:inline-flex;align-items:center;gap:6px;color:#64748b;font-size:12px;font-weight:900}.submit-line{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:16px;align-items:center;margin-top:16px;padding-top:14px;border-top:1px solid #eef2f7}.submit-spacer{color:#94a3b8;font-size:12px;line-height:1.7}.submit-summary{display:grid;grid-template-columns:auto auto auto;column-gap:7px;row-gap:8px;align-items:baseline;justify-content:end;font-size:14px;color:#64748b;line-height:1;text-align:right;min-width:184px}.submit-summary strong{color:#111827;font-size:22px;line-height:1;font-variant-numeric:tabular-nums}.submit-line .btn{height:52px!important;border-radius:999px!important;padding:0 24px!important;flex:0 0 auto;align-self:center}.redeem-form{display:grid;gap:10px}.redeem-form .btn{height:38px!important;border-radius:999px!important}.notice-list{margin:0;padding-left:18px;color:#94a3b8;font-size:12px;line-height:1.9}.empty-tip{padding:22px;border-radius:16px;background:#f8fafc;color:#94a3b8;text-align:center;font-size:13px}.mode-panel{display:none}.mode-panel.active{display:block}@media(max-width:760px){.recharge-page{padding:16px 12px 56px}.recharge-head{display:block}.wallet-link{margin-top:10px}.recharge-grid{grid-template-columns:1fr}.package-list{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.package-option{min-height:92px;border-radius:14px}.package-option b{font-size:15px}.package-option span{font-size:11px}.submit-line{grid-template-columns:1fr auto;gap:12px}.submit-spacer{grid-column:1/-1}.submit-summary{justify-self:end;min-width:168px}.submit-summary strong{font-size:20px}.submit-line .btn{height:50px!important;padding:0 20px!important}.asset-current{align-items:flex-start}.asset-current strong{font-size:26px}.submit-line{display:grid}.submit-line .btn{width:100%}}
html[data-theme="dark"] .recharge-page{background:#0f172a}html[data-theme="dark"] .asset-panel,html[data-theme="dark"] .recharge-card{background:#111827;border-color:#263244}html[data-theme="dark"] .recharge-title,html[data-theme="dark"] .asset-current strong,html[data-theme="dark"] .card-title,html[data-theme="dark"] .package-option b,html[data-theme="dark"] .submit-summary strong{color:#e5e7eb}html[data-theme="dark"] .package-option,html[data-theme="dark"] .wallet-link{background:#0f172a;border-color:#263244}html[data-theme="dark"] .custom-result,html[data-theme="dark"] .empty-tip,html[data-theme="dark"] .currency-tabs a,html[data-theme="dark"] .mode-tabs button{background:#0f172a;border-color:#263244}
@media(max-width:420px){.package-list{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.package-option{min-height:86px;padding:10px 5px}.package-option b{font-size:14px}.package-option span{font-size:10px}}</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="recharge-page"><div class="recharge-shell"><header class="recharge-head"><div><h1 class="recharge-title">钱包充值</h1><div class="recharge-sub">选择要充值的货币，确认金额后即可创建订单。</div></div><a class="wallet-link" href="/index.php?path=wallet">返回钱包</a></header><?php if($message): ?><div class="alert ok"><?= htmlspecialchars($message) ?></div><?php endif; ?><?php if($error): ?><div class="alert err"><?= htmlspecialchars($error) ?></div><?php endif; ?><section class="asset-panel"><div class="asset-current"><div><span>当前资产</span><strong><?= number_format($balance,$precision) ?> <?= htmlspecialchars($currencyName) ?></strong></div><div><span>当前换算</span><strong style="font-size:18px;">1 元 ≈ <?= $ratio>0?currency_trim_amount($ratio):'未配置' ?> <?= htmlspecialchars($currencyName) ?></strong></div></div><?php if(count($balances)>1): ?><div class="currency-tabs"><?php foreach($balances as $b): ?><a class="<?= (string)$b['currency_code']===$currency?'active':'' ?>" href="/index.php?path=wallet/recharge&currency=<?= urlencode($b['currency_code']) ?>"><?= htmlspecialchars($b['name']??$b['currency_code']) ?></a><?php endforeach; ?></div><?php endif; ?></section><div class="recharge-grid"><section class="recharge-card"><div class="card-title">创建充值订单</div><div class="card-desc">选择套餐或输入自定义金额，页面会自动计算预计到账数量。</div><form method="post" action="/index.php?path=payment/create" id="payForm"><?= csrf_field() ?><input type="hidden" name="currency_code" value="<?= htmlspecialchars($currency) ?>"><input type="hidden" name="package_id" id="packageId"><input type="hidden" name="pay_amount" id="customPay"><div class="mode-tabs"><button type="button" class="active" data-mode="package">选择套餐</button><button type="button" data-mode="custom" <?= $ratio<=0?'disabled title="当前货币暂不可自定义充值"':'' ?>>自定义金额</button></div><div class="mode-panel active" data-panel="package"><?php if($packages): ?><div class="package-list"><?php foreach($packages as $i=>$pkg): ?><button type="button" class="package-option <?= $i===0?'active':'' ?>" data-id="<?= (int)$pkg['id'] ?>" data-amount="<?= htmlspecialchars((string)$pkg['amount']) ?>" data-pay="<?= htmlspecialchars((string)$pkg['pay_amount']) ?>"><b><?= number_format((float)$pkg['amount'],(int)($pkg['precision']??0)) ?> <?= htmlspecialchars($pkg['currency_name']??$pkg['currency_code']) ?></b><span>支付 <?= currency_trim_amount($pkg['pay_amount'],2) ?> 元</span></button><?php endforeach; ?></div><?php else: ?><div class="empty-tip">当前货币暂无充值套餐。</div><?php endif; ?></div><div class="mode-panel custom-panel" data-panel="custom"><?php if($ratio>0): ?><input class="input" type="number" step="0.01" min="1" id="customPayInput" placeholder="输入付款金额，最低 1 元"><div class="custom-result">预计到账：<strong id="customAmountText">0</strong> <?= htmlspecialchars($currencyName) ?></div><?php else: ?><div class="empty-tip">当前货币暂不可自定义充值。</div><?php endif; ?></div><div class="pay-methods"><?php foreach($channels as $code=>$ch): ?><label><input type="radio" name="channel" value="<?= htmlspecialchars($code) ?>" <?= $code===array_key_first($channels)?'checked':'' ?>> <?= htmlspecialchars($ch['name']) ?></label><?php endforeach; ?><?php if(empty($channels)): ?><span style="color:#ef4444;font-size:13px;">暂无可用支付方式，请联系管理员。</span><?php endif; ?></div><div class="submit-line"><div class="submit-spacer">确认金额后提交订单</div><div class="submit-summary"><span>付款</span><strong id="payText">0</strong><span>元</span><span>到账</span><strong id="amountText">0</strong><span><?= htmlspecialchars($currencyName) ?></span></div><button class="btn" type="submit" <?= empty($channels)?'disabled':'' ?>>提交订单</button></div></form></section><aside class="recharge-card"><div class="card-title">兑换码兑换</div><div class="card-desc">兑换码不创建支付订单，验证通过后直接到账。</div><form method="post" action="/index.php?path=payment/redeem" class="redeem-form"><?= csrf_field() ?><input class="input" name="code" placeholder="输入兑换码"><button class="btn btn-light" type="submit">立即兑换</button></form><div style="height:18px"></div><div class="card-title" style="font-size:15px;">充值说明</div><ul class="notice-list"><li>支付成功后自动入账。</li><li>扫码支付以自动回调入账为准，若回调延迟可在订单页刷新同步。</li><li>自定义充值会自动计算预计到账数量。</li></ul></aside></div></div></main><script>(function(){const modeBtns=[...document.querySelectorAll('[data-mode]')],panels=[...document.querySelectorAll('[data-panel]')],opts=[...document.querySelectorAll('.package-option')],pid=document.getElementById('packageId'),cp=document.getElementById('customPay'),payText=document.getElementById('payText'),amountText=document.getElementById('amountText'),customInput=document.getElementById('customPayInput'),customAmountText=document.getElementById('customAmountText');const ratio=<?= json_encode($ratio) ?>;let mode='package';function fmt(v){return Number(v||0).toFixed(6).replace(/\\.?0+$/,'')}function set(pay,amount,id){cp.value=pay||'';pid.value=id||'';payText.textContent=fmt(pay);amountText.textContent=fmt(amount);if(customAmountText)customAmountText.textContent=fmt(amount)}function activateMode(m){mode=m;modeBtns.forEach(b=>b.classList.toggle('active',b.dataset.mode===m));panels.forEach(p=>p.classList.toggle('active',p.dataset.panel===m));if(m==='custom'){if(!ratio){activateMode('package');return}const pay=Number(customInput?customInput.value:0);set(pay,pay*ratio,'')}else{const active=document.querySelector('.package-option.active')||opts[0];if(active){active.classList.add('active');set(active.dataset.pay,active.dataset.amount,active.dataset.id)}else set(0,0,'')}}modeBtns.forEach(b=>b.onclick=()=>activateMode(b.dataset.mode));opts.forEach(o=>o.onclick=()=>{opts.forEach(x=>x.classList.remove('active'));o.classList.add('active');set(o.dataset.pay,o.dataset.amount,o.dataset.id)});customInput&&customInput.addEventListener('input',()=>{const pay=Number(customInput.value||0);set(pay,pay*ratio,'')});activateMode('package');})();</script><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?></body></html>
